// 運算後端統一介面與登錄表（DESIGN.TODO.offline-training-studio.md §5.3）。純核心、依賴注入、不碰 window。\nconst BACKEND_IDS = ['cpu-js', 'cpu-py', 'webgpu', 'directml', 'vulkan'];\nconst SYMBOLIC_KINDS = ['trainer', 'colu', 'uml', 'blockly', 'matrix'];\n// 每個 kind 宣告支援的後端；lora 的清單是「可能」，實際是否點亮由 probe＋基準測試決定。符號式五類只有 cpu-js。\nconst KIND_BACKENDS = { trainer: ['cpu-js'], colu: ['cpu-js'], uml: ['cpu-js'], blockly: ['cpu-js'], matrix: ['cpu-js'], lora: ['cpu-py', 'webgpu', 'directml', 'vulkan'] };\n// 「自動」同速（差 <10%）時偏好較成熟者：cpu-py > vulkan > directml > webgpu（cpu-js 只服務符號式，排最前）\nconst MATURITY = ['cpu-js', 'cpu-py', 'vulkan', 'directml', 'webgpu'];\n\nconst REQUIRED_METHODS = ['probe', 'benchmark', 'init', 'step', 'evalLoss', 'saveCheckpoint', 'loadCheckpoint', 'dispose'];\n\n// probe 結果形狀：不丟例外；available 為 false 時 reason 必須是給使用者看的具體原因\nfunction probeResult(available, reason, device, fingerprint) {\n  const r = { available: !!available, device: device || { name: '' }, fingerprint: fingerprint || {} };\n  if (reason) r.reason = String(reason);\n  return r;\n}\nfunction validateProbeResult(r) {\n  const errs = [];\n  if (!r || typeof r !== 'object') return ['probe 沒回物件'];\n  if (typeof r.available !== 'boolean') errs.push('available 必須是 boolean');\n  if (!r.available && (typeof r.reason !== 'string' || !r.reason)) errs.push('不可用時必須有 reason');\n  if (!r.device || typeof r.device !== 'object') errs.push('缺 device');\n  if (!r.fingerprint || typeof r.fingerprint !== 'object') errs.push('缺 fingerprint');\n  return errs;\n}\n// 介面型別檢查：id 合法、方法齊全；capabilities 標明「逐步呼叫」或「整段子行程」\nfunction validateBackend(b) {\n  const errs = [];\n  if (!b || typeof b !== 'object') return ['不是物件'];\n  if (BACKEND_IDS.indexOf(b.id) < 0) errs.push('id 不在 ' + BACKEND_IDS.join('／'));\n  REQUIRED_METHODS.forEach((m) => { if (typeof b[m] !== 'function') errs.push('缺方法 ' + m); });\n  if (!b.capabilities || typeof b.capabilities.perStep !== 'boolean') errs.push('缺 capabilities.perStep');\n  return errs;\n}\n// 保證 probe 不丟例外（後端自己寫壞時也不拖垮 UI）\nasync function safeProbe(b, ctx) {\n  try { const r = await b.probe(ctx); const e = validateProbeResult(r); return e.length ? probeResult(false, '後端 ' + b.id + ' 的 probe 回傳格式不合：' + e.join('；')) : r; }\n  catch (e) { return probeResult(false, '後端 ' + b.id + ' 的 probe 發生例外：' + (e && e.message || e)); }\n}\n\nclass BackendRegistry {\n  constructor() { this.map = new Map(); }\n  register(b) { const e = validateBackend(b); if (e.length) throw new Error('後端不合介面：' + e.join('；')); this.map.set(b.id, b); return this; }\n  get(id) { return this.map.get(id) || null; }\n  ids() { return Array.from(this.map.keys()); }\n  supportedFor(kind) { return (KIND_BACKENDS[kind] || []).slice(); }\n  // 某 kind 的後端清單（含未登錄者的說明，供 UI 灰掉並顯示原因）\n  async listFor(kind, ctx) {\n    const out = [];\n    for (const id of this.supportedFor(kind)) {\n      const b = this.get(id);\n      if (!b) { out.push({ id, available: false, reason: '後端 ' + id + ' 沒有登錄', probe: null }); continue; }\n      const p = await safeProbe(b, ctx); out.push({ id, available: p.available, reason: p.reason || '', probe: p });\n    }\n    return out;\n  }\n}\nconst isSymbolicKind = (k) => SYMBOLIC_KINDS.indexOf(k) >= 0;\nconst maturityRank = (id) => { const i = MATURITY.indexOf(id); return i < 0 ? 99 : i; };\n\nmodule.exports = { BACKEND_IDS, SYMBOLIC_KINDS, KIND_BACKENDS, MATURITY, REQUIRED_METHODS, probeResult, validateProbeResult, validateBackend, safeProbe, BackendRegistry, isSymbolicKind, maturityRank };\n","bench_core.js":"'use strict';\n// 基準測試、一致性檢查、結果快取與自動選擇（DESIGN.TODO.offline-training-studio.md §4.1、§5.8）。純核心、依賴注入（時鐘、儲存、記錄都由呼叫端給）。\nconst crypto = require('crypto');\nconst B = require('./backend_core.js');\n\n// §5.8 設計初值（階段 2 以真實測量校準後才固定）\nconst BENCH = { warmup: 3, steps: 30, samples: 16, seqLen: 256, batch: 1, deadlineMs: 60000, abortWithinMs: 3000 };\nconst CONSIST = { loss1: 1e-3, gradNorm1: 1e-2, loss30: 0.03, loss30Fp16: 0.05 };\nconst TIE = 0.10;       // 同速：差 <10%\n\n// 基準本身也要遵守「電腦保持可用」：核心數上限 N−1，至少 1\nconst benchThreads = (cores) => Math.max(1, (cores | 0) - 1);\n\nconst rel = (a, b) => Math.abs(a - b) / Math.max(Math.abs(b), 1e-12);\nfunction percentile(sorted, p) { if (!sorted.length) return 0; const i = Math.min(sorted.length - 1, Math.max(0, Math.ceil(p * sorted.length) - 1)); return sorted[i]; }\nconst finite = (x) => typeof x === 'number' && Number.isFinite(x);\n\n// ---- 一致性檢查四項（以參考後端的 trace 為準）----\n// trace = { loss1, gradNorm1, loss30, hasNonFinite }\nfunction consistencyCheck(ref, cand, o) {\n  o = o || {}; const fp16 = !!o.fp16;\n  const items = [\n    { name: '第1步loss', value: rel(cand.loss1, ref.loss1), tol: CONSIST.loss1 },\n    { name: '第1步梯度範數', value: rel(cand.gradNorm1, ref.gradNorm1), tol: CONSIST.gradNorm1 },\n    { name: '30步後loss', value: rel(cand.loss30, ref.loss30), tol: fp16 ? CONSIST.loss30Fp16 : CONSIST.loss30 },\n  ].map((x) => Object.assign(x, { pass: finite(x.value) && x.value <= x.tol }));\n  items.push({ name: '全程無NaN或Inf', value: cand.hasNonFinite ? 1 : 0, tol: 0, pass: !cand.hasNonFinite });\n  const failed = items.filter((x) => !x.pass).map((x) => x.name);\n  return { pass: failed.length === 0, items, failed, fp16, maxRelErr: Math.max(items[0].value, items[1].value), lossDelta: items[2].value };\n}\n\n// ---- 可中斷的逐步基準（perStep 後端共用）----\n// opts: { signal, now(), reference(trace), fp16, isReference, deadlineMs, warmup, steps, tokensPerStep }\n// cfg.makeBatch(i) 給第 i 步的批次（固定種子的 16 筆樣本由呼叫端決定）\nasync function stepBenchmark(backend, cfg, opts) {\n  opts = opts || {}; const now = opts.now || (typeof performance !== 'undefined' ? () => performance.now() : () => Date.now()), signal = opts.signal || null;\n  const warm = opts.warmup === undefined ? BENCH.warmup : opts.warmup, steps = opts.steps === undefined ? BENCH.steps : opts.steps;\n  const deadline = opts.deadlineMs === undefined ? BENCH.deadlineMs : opts.deadlineMs, tokens = opts.tokensPerStep || (BENCH.seqLen * BENCH.batch);\n  const t0 = now(); let abortedAt = null, handle = null, tooSlow = false;\n  let abortReject; const abortP = new Promise((_, rej) => { abortReject = rej; });\n  abortP.catch(() => {});\n  const onAbort = () => { if (abortedAt === null) abortedAt = now(); abortReject(new Error('__aborted__')); };\n  if (signal) { if (signal.aborted) onAbort(); else if (signal.addEventListener) signal.addEventListener('abort', onAbort, { once: true }); }\n  const guard = (p) => Promise.race([Promise.resolve(p), abortP]);       // 單步卡住也能在中斷後立刻返回\n  const times = [], losses = []; let gn1 = null, nonFinite = false, peak = 0, err = null;\n  try {\n    handle = await guard(backend.init(null, Object.assign({}, cfg, { threads: cfg.threads || benchThreads(cfg.cores || 2) })));\n    for (let i = 0; i < warm + steps; i++) {\n      if (abortedAt !== null) break;\n      if (now() - t0 > deadline) { tooSlow = true; break; }\n      const s0 = now(); const r = await guard(backend.step(handle, cfg.makeBatch ? cfg.makeBatch(i) : { index: i })); const dt = now() - s0;\n      if (!finite(r.loss) || (r.gradNorm !== undefined && !finite(r.gradNorm))) nonFinite = true;\n      if (i === 0) gn1 = r.gradNorm;\n      if (i >= warm) { times.push(dt); losses.push(r.loss); }\n      else if (i === 0) losses.unshift(r.loss);   // 第 1 步 loss 放最前面當 loss1（暖機的其餘步不計入速度）\n      if (backend.peakMemBytes) { try { peak = Math.max(peak, backend.peakMemBytes(handle) || 0); } catch (e) {} }\n    }\n  } catch (e) { if (!(e && e.message === '__aborted__')) err = e; }\n  finally {\n    if (signal && signal.removeEventListener) signal.removeEventListener('abort', onAbort);\n    if (handle) { try { await Promise.race([Promise.resolve(backend.dispose(handle)), new Promise((r) => setTimeout(r, 2000))]); } catch (e) {} }\n  }\n  const stoppedAfterMs = abortedAt === null ? null : now() - abortedAt;\n  if (abortedAt !== null) return { ok: false, aborted: true, stoppedAfterMs, elapsedMs: now() - t0, reason: '使用者中斷' };\n  if (err) return { ok: false, error: String(err && err.message || err), reason: '基準測試失敗：' + (err && err.message || err), elapsedMs: now() - t0 };\n  if (tooSlow) return { ok: false, tooSlow: true, reason: '太慢：超過 ' + Math.round(deadline / 1000) + ' 秒仍未跑完 ' + (warm + steps) + ' 步', elapsedMs: now() - t0 };\n  const sorted = times.slice().sort((a, b) => a - b), med = percentile(sorted, 0.5);\n  const trace = { loss1: losses[0], gradNorm1: gn1, loss30: losses[losses.length - 1], hasNonFinite: nonFinite };\n  const res = { ok: true, tokPerSec: med > 0 ? tokens / (med / 1000) : 0, peakMemBytes: peak || null, stepMsP50: med, stepMsP95: percentile(sorted, 0.95), samples: times.length, trace, elapsedMs: now() - t0, threads: cfg.threads || benchThreads(cfg.cores || 2), fp16: !!opts.fp16 };\n  if (opts.isReference) res.numericCheck = { pass: !nonFinite, maxRelErr: 0, lossDelta: 0, reference: true, items: [], failed: nonFinite ? ['全程無NaN或Inf'] : [] };\n  else if (opts.reference) { const c = consistencyCheck(opts.reference, trace, { fp16: opts.fp16 }); res.numericCheck = { pass: c.pass, maxRelErr: c.maxRelErr, lossDelta: c.lossDelta, items: c.items, failed: c.failed }; }\n  else res.numericCheck = { pass: false, maxRelErr: null, lossDelta: null, items: [], failed: ['沒有參考後端的結果可比對'] };\n  return res;\n}\n// 通過門檻：四項全過、沒超時、沒錯誤才算通過（才可被「自動」選用）\nconst benchPassed = (r) => !!(r && r.ok && !r.tooSlow && r.numericCheck && r.numericCheck.pass);\n\n// ---- 快取：以硬體指紋為鍵 ----\nfunction stableStringify(o) { if (o === null || typeof o !== 'object') return JSON.stringify(o); if (Array.isArray(o)) return '[' + o.map(stableStringify).join(',') + ']'; return '{' + Object.keys(o).sort().map((k) => JSON.stringify(k) + ':' + stableStringify(o[k])).join(',') + '}'; }\nconst hashFingerprint = (fp) => crypto.createHash('sha256').update(stableStringify(fp || {})).digest('hex').slice(0, 16);\nfunction diffFingerprint(a, b) { const keys = new Set(Object.keys(a || {}).concat(Object.keys(b || {}))), out = []; keys.forEach((k) => { if (stableStringify((a || {})[k]) !== stableStringify((b || {})[k])) out.push(k); }); return out; }\n// store: { load() -> obj|null, save(obj) }（可非同步）；沒給就用記憶體\nfunction createBenchCache(store, now) {\n  now = now || (() => Date.now()); let mem = null;\n  const load = async () => { if (mem) return mem; let d = null; try { d = store ? await store.load() : null; } catch (e) {} mem = d && d.version === 1 ? d : { version: 1, entries: {}, latest: {} }; return mem; };\n  const persist = async () => { if (store) try { await store.save(mem); } catch (e) {} };\n  return {\n    // 回傳 {status:'hit'|'stale'|'none', result?, changed?}\n    async lookup(id, fp) {\n      const d = await load(), h = hashFingerprint(fp), e = d.entries[id + '|' + h];\n      if (e) return { status: 'hit', result: e.result, at: e.at };\n      const last = d.latest[id]; return last ? { status: 'stale', changed: diffFingerprint(last.fingerprint, fp), previous: last } : { status: 'none' };\n    },\n    async store(id, fp, result) { const d = await load(), h = hashFingerprint(fp); const slim = Object.assign({}, result); d.entries[id + '|' + h] = { result: slim, at: now(), fingerprint: fp }; d.latest[id] = { hash: h, fingerprint: fp }; await persist(); },\n    async clear() { mem = { version: 1, entries: {}, latest: {} }; await persist(); },\n  };\n}\n\n// ---- 自動選擇 ----\n// o: { kind, registry, cache, ctx(傳給 probe；ctx.modelSha256 併入指紋), pin, skipBench, runBench(id, signal)->結果, signal, log(rec) }\nasync function autoSelect(o) {\n  const log = o.log || (() => {}), events = [];\n  const ev = (rec) => { events.push(rec); log(rec); };\n  if (B.isSymbolicKind(o.kind)) return { chosen: 'cpu-js', order: ['cpu-js'], source: 'symbolic', needsRebench: false, stale: [], events, reason: '符號式訓練只需處理器（cpu-js）' };\n  const ids = o.registry.supportedFor(o.kind), probes = {}, fps = {};\n  for (const id of ids) {\n    const b = o.registry.get(id);\n    probes[id] = b ? await B.safeProbe(b, o.ctx) : B.probeResult(false, '後端 ' + id + ' 沒有登錄');\n    fps[id] = Object.assign({}, probes[id].fingerprint, { model_sha256: (o.ctx && o.ctx.modelSha256) || null, backend: id });\n  }\n  const avail = ids.filter((id) => probes[id].available);\n  // 釘選：不自動換；不可用就停下詢問\n  if (o.pin) {\n    if (probes[o.pin] && probes[o.pin].available) {\n      const c = await o.cache.lookup(o.pin, fps[o.pin]);\n      return { chosen: o.pin, order: [o.pin], pinned: true, stopOnFail: true, source: 'pin', needsRebench: c.status !== 'hit', stale: [], warning: c.status === 'hit' && !benchPassed(c.result) ? '釘選的後端未通過一致性檢查：' + ((c.result.numericCheck && c.result.numericCheck.failed) || [c.result.reason]).join('、') : '', events };\n    }\n    return { chosen: null, order: [], pinned: true, ask: true, source: 'pin', needsRebench: false, stale: [], events, reason: '釘選的後端 ' + o.pin + ' 不可用：' + ((probes[o.pin] && probes[o.pin].reason) || '沒有這個後端') + '；要改用別的後端嗎？' };\n  }\n  if (!avail.length) return { chosen: null, order: [], source: 'none', needsRebench: false, stale: [], events, reason: '沒有可用的後端：' + ids.map((i) => i + '＝' + probes[i].reason).join('；') };\n  const results = {}, stale = []; const missing = [];\n  for (const id of avail) {\n    const c = await o.cache.lookup(id, fps[id]);\n    if (c.status === 'hit') results[id] = c.result;\n    else { missing.push(id); if (c.status === 'stale') { stale.push({ id, changed: c.changed }); ev({ at: 'cache_stale', backend: id, changed: c.changed, text: id + ' 的硬體指紋改變（' + c.changed.join('、') + '），快取失效，需重新跑基準測試' }); } }\n  }\n  let source = missing.length ? 'benchmark' : 'cache';\n  if (missing.length && o.skipBench) {\n    // 略過基準：用 cpu-py（沒有就停下詢問，不拿未驗證的後端硬上）\n    ev({ at: 'bench_skipped', text: '略過基準測試，使用 cpu-py' });\n    if (probes['cpu-py'] && probes['cpu-py'].available) return { chosen: 'cpu-py', order: ['cpu-py'], source: 'skip-bench', needsRebench: true, stale, events };\n    return { chosen: null, order: [], ask: true, source: 'skip-bench', needsRebench: true, stale, events, reason: '略過基準測試時預設用 cpu-py，但它不可用：' + probes['cpu-py'].reason };\n  }\n  for (const id of missing) {\n    if (o.signal && o.signal.aborted) { ev({ at: 'bench_aborted', backend: id, text: '基準測試被中斷' }); return { chosen: null, order: [], aborted: true, source: 'benchmark', needsRebench: true, stale, events, reason: '基準測試被使用者中斷' }; }\n    let r; try { r = await o.runBench(id, o.signal); } catch (e) { r = { ok: false, error: String(e && e.message || e), reason: '基準測試丟出例外：' + (e && e.message || e) }; }\n    if (r && r.aborted) { ev({ at: 'bench_aborted', backend: id, text: '基準測試被中斷' }); return { chosen: null, order: [], aborted: true, source: 'benchmark', needsRebench: true, stale, events, reason: '基準測試被使用者中斷' }; }\n    if (!benchPassed(r)) ev({ at: 'bench_failed', backend: id, text: id + ' 基準測試未通過：' + (r && (r.reason || (r.numericCheck && r.numericCheck.failed && r.numericCheck.failed.join('、'))) || '未知原因') });\n    results[id] = r; await o.cache.store(id, fps[id], r);\n  }\n  const cands = avail.filter((id) => benchPassed(results[id]));\n  if (!cands.length) return { chosen: null, order: [], source, needsRebench: false, stale, events, reason: '可用的後端都沒通過基準測試／一致性檢查：' + avail.map((i) => i + '＝' + ((results[i] && (results[i].reason || (results[i].numericCheck && results[i].numericCheck.failed.join('、')))) || '無結果')).join('；') };\n  const speed = (id) => results[id].tokPerSec || 0, top = Math.max.apply(null, cands.map(speed));\n  const cmp = (a, b) => { const na = speed(a) >= top * (1 - TIE), nb = speed(b) >= top * (1 - TIE); if (na && nb) return B.maturityRank(a) - B.maturityRank(b) || speed(b) - speed(a); if (na !== nb) return na ? -1 : 1; return speed(b) - speed(a); };\n  const order = cands.slice().sort(cmp);\n  return { chosen: order[0], order, source, needsRebench: false, stale, events, table: avail.map((id) => ({ id, result: results[id], passed: benchPassed(results[id]) })) };\n}\n\n// ---- 失敗自動降級（訓練中後端失敗：已存檢查點，換下一個候選）----\nfunction degrade(o) {   // o: { order, failed, step, reason, pinned, log }\n  const log = o.log || (() => {});\n  if (o.pinned) { const m = '釘選的後端 ' + o.failed + ' 失敗（' + o.reason + '，step=' + o.step + '），已停下；要換成別的後端嗎？'; log({ at: 'pinned_failed', backend: o.failed, step: o.step, reason: o.reason, text: m }); return { stop: true, ask: m }; }\n  const rest = (o.order || []).filter((x) => x !== o.failed), to = rest[0];\n  if (!to) { const m = '後端 ' + o.failed + ' 失敗（' + o.reason + '，step=' + o.step + '），沒有可降級的候選'; log({ at: 'degrade_none', backend: o.failed, step: o.step, reason: o.reason, text: m }); return { stop: true, message: m }; }\n  const text = '由 ' + o.failed + ' 後端失敗降級到 ' + to + '，原因：' + o.reason + '，降級時 step=' + o.step;\n  log({ at: 'degrade', from: o.failed, to, step: o.step, reason: o.reason, text });\n  return { stop: false, to, order: rest, message: text, needsCrossBackendCheck: true };\n}\n\nmodule.exports = { BENCH, CONSIST, TIE, benchThreads, percentile, consistencyCheck, stepBenchmark, benchPassed, stableStringify, hashFingerprint, diffFingerprint, createBenchCache, autoSelect, degrade };\n","backend_cpu_js.js":"'use strict';\n// cpu-js 後端：純 JS 處理器計算（DESIGN.TODO.offline-training-studio.md §5.2、§5.3）。\n// 符號式五類（trainer／colu／uml／blockly／matrix）本來就是純 JS，只宣告這個後端；真正的訓練引擎由呼叫端用 engineFactory 注入。\n// 內建的「迷你訓練器」是真的 AdamW＋PCG32＋資料游標＋規範化檢查點計算（float32），但它是縮小版的 LoRA 形狀（pred = (x·A)·B），\n// 不是 Qwen3 的訓練：用途是 (1) 基準測試與一致性檢查的參考引擎、(2) 暫停／續訓與檢查點往返的模擬驗證。\nconst C = require('./checkpoint_core.js');\nconst B = require('./backend_core.js');\nconst BC = require('./bench_core.js');\nconst f = Math.fround;\n\nconst DEFAULTS = { dim: 8, rank: 2, nSamples: 16, batch: 1, lr: 0.01, betas: [0.9, 0.999], eps: 1e-8, wd: 0.01, warmup: 3, total: 200, dropout: 0.1, seed: 1234, dataSeed: 99, orderSeed: 7, seqLen: 256, evalBatch: [0, 1, 2, 3] };\n\nfunction makeData(cfg) {\n  const g = new C.PCG32(cfg.dataSeed, 3), w = []; for (let i = 0; i < cfg.dim; i++) w.push(g.nextNormal());\n  const X = [], Y = [];\n  for (let n = 0; n < cfg.nSamples; n++) { const x = []; let y = 0; for (let i = 0; i < cfg.dim; i++) { const v = f(g.nextNormal()); x.push(v); y += w[i] * v; } X.push(x); Y.push(f(y + 0.05 * g.nextNormal())); }\n  const sha = C.sha256(Buffer.from(JSON.stringify({ X, Y }))); return { X, Y, sha };\n}\nconst lrAt = (cfg, t) => cfg.warmup > 0 && t < cfg.warmup ? cfg.lr * (t + 1) / cfg.warmup : cfg.lr * Math.max(0.1, 1 - (t - cfg.warmup) / Math.max(1, cfg.total - cfg.warmup));\n\nfunction createTinyEngine(userCfg) {\n  const cfg = Object.assign({}, DEFAULTS, userCfg || {}), data = makeData(cfg), D = cfg.dim, R = cfg.rank;\n  const rng = new C.PCG32(cfg.seed, 11);\n  const A = new Float32Array(D * R).map(() => f(0.3 * rng.nextNormal())), Bm = new Float32Array(R);   // B 為零（LoRA 慣例）\n  const z = (n) => new Float32Array(n);\n  const st = { cfg, data, A, B: Bm, m: { A: z(D * R), B: z(R) }, v: { A: z(D * R), B: z(R) }, step: 0, cursor: C.createCursor(cfg.orderSeed), rng, lossTail: [], disposed: false };\n  return st;\n}\nfunction forward(st, xs, drop) {         // 回傳 pred 與中間量\n  const D = st.cfg.dim, R = st.cfg.rank, h = new Float32Array(R);\n  for (let j = 0; j < R; j++) { let s = 0; for (let i = 0; i < D; i++) if (i !== drop) s = f(s + f(xs[i] * st.A[i * R + j])); h[j] = s; }\n  let p = 0; for (let j = 0; j < R; j++) p = f(p + f(h[j] * st.B[j])); return { p, h };\n}\nfunction lossOver(st, idx) { let s = 0; idx.forEach((k) => { const e = forward(st, st.data.X[k], -1).p - st.data.Y[k]; s += e * e; }); return f(s / idx.length); }\nfunction tinyStep(st, batch) {\n  const cfg = st.cfg, D = cfg.dim, R = cfg.rank; let idx = batch && batch.indices;\n  if (!idx) { const r = C.nextIndices(st.cursor, cfg.nSamples, cfg.batch); idx = r.indices; st.cursor = r.cursor; }\n  st.cursor.consumed_tokens += cfg.seqLen * idx.length;\n  const drop = st.rng.nextFloat() < cfg.dropout ? st.rng.nextBelow(D) : -1;      // 亂數狀態會影響結果：續訓若沒還原就會偏掉\n  const gA = new Float32Array(D * R), gB = new Float32Array(R); let loss = 0;\n  idx.forEach((k) => {\n    const xs = st.data.X[k], fw = forward(st, xs, drop), e = f(fw.p - st.data.Y[k]); loss += e * e;\n    for (let j = 0; j < R; j++) { gB[j] = f(gB[j] + f(2 * e * fw.h[j] / idx.length)); for (let i = 0; i < D; i++) if (i !== drop) gA[i * R + j] = f(gA[i * R + j] + f(2 * e * st.B[j] * xs[i] / idx.length)); }\n  });\n  loss = f(loss / idx.length);\n  const t = st.step + 1, lr = lrAt(cfg, st.step), b1 = cfg.betas[0], b2 = cfg.betas[1];\n  const upd = (P, G, M, V) => { for (let i = 0; i < P.length; i++) { M[i] = f(b1 * M[i] + (1 - b1) * G[i]); V[i] = f(b2 * V[i] + (1 - b2) * G[i] * G[i]); const mh = M[i] / (1 - Math.pow(b1, t)), vh = V[i] / (1 - Math.pow(b2, t)); P[i] = f(P[i] - lr * cfg.wd * P[i] - lr * mh / (Math.sqrt(vh) + cfg.eps)); } };\n  let gn = 0; gA.forEach((x) => { gn += x * x; }); gB.forEach((x) => { gn += x * x; }); gn = f(Math.sqrt(gn));\n  upd(st.A, gA, st.m.A, st.v.A); upd(st.B, gB, st.m.B, st.v.B);\n  st.step = t; st.lossTail.push(loss); if (st.lossTail.length > 50) st.lossTail.shift();\n  return { loss, gradNorm: gn };\n}\nfunction tinySave(st, produced) {\n  const cfg = st.cfg, T = (name, shape, d) => [{ name, shape, data: d }];\n  const evalLoss = lossOver(st, cfg.evalBatch);\n  return C.makeCheckpoint({\n    step: st.step, epoch: st.cursor.epoch, cursor: Object.assign({}, st.cursor), rng: st.rng.snapshot(),\n    optimizer: { kind: 'adamw', lr: cfg.lr, betas: cfg.betas, eps: cfg.eps, wd: cfg.wd, step_count: st.step, schedule: { type: 'linear', warmup: cfg.warmup, total: cfg.total } },\n    data_sha256: st.data.sha, compat: compatOf(cfg), loss_tail: st.lossTail.slice(), eval_check: { batch: cfg.evalBatch, loss: evalLoss },\n    produced_by: Object.assign({ backend: 'cpu-js', device_fingerprint: 'js', engine_version: 'tiny-1', precision: 'float32' }, produced || {}),\n    tensors: { 'lora_A.f32': T('A', [cfg.dim, cfg.rank], st.A), 'lora_B.f32': T('B', [cfg.rank, 1], st.B), 'opt_m.f32': T('A', [cfg.dim, cfg.rank], st.m.A).concat(T('B', [cfg.rank, 1], st.m.B)), 'opt_v.f32': T('A', [cfg.dim, cfg.rank], st.v.A).concat(T('B', [cfg.rank, 1], st.v.B)) },\n  });\n}\nfunction compatOf(cfg) { return { base: 'tiny-lora', base_sha256: 'tiny', rank: cfg.rank, alpha: cfg.rank * 2, target_modules: ['A', 'B'], prompt_format_version: 1, tool_catalog_sha256: 'none' }; }\nfunction tinyLoad(st, cp) {\n  const v = C.verifyChecksums(cp); if (!v.ok) throw new Error('檢查點驗證失敗：' + v.bad.join('、'));\n  const cc = C.checkCompat(cp.ckpt, { compat: compatOf(st.cfg), data_sha256: st.data.sha, optimizer: { kind: 'adamw' } });\n  if (!cc.ok) { const e = new Error(cc.message); e.compat = cc; throw e; }\n  const d = (file) => C.decodeTensors(cp.files[file]), by = (l, n) => l.find((x) => x.name === n).data;\n  const a = d('lora_A.f32'), b = d('lora_B.f32'), m = d('opt_m.f32'), vv = d('opt_v.f32');\n  st.A.set(by(a, 'A')); st.B.set(by(b, 'B')); st.m.A.set(by(m, 'A')); st.m.B.set(by(m, 'B')); st.v.A.set(by(vv, 'A')); st.v.B.set(by(vv, 'B'));\n  st.step = cp.ckpt.step; st.cursor = Object.assign({}, cp.ckpt.cursor); st.rng = C.PCG32.fromSnapshot(cp.ckpt.rng); st.lossTail = (cp.ckpt.loss_tail || []).slice();\n}\n\n// engineFactory：符號式五類的真引擎由此注入，需提供 { step(batch), evalLoss(batch), save(), load(cp), dispose() }；預設為迷你訓練器\nfunction createCpuJsBackend(o) {\n  o = o || {};\n  const b = {\n    id: 'cpu-js', capabilities: { perStep: true, run: false, fp16: false }, kinds: B.KIND_BACKENDS,\n    async probe(ctx) {\n      const hw = (ctx && ctx.hw) || {};\n      return B.probeResult(true, '', { name: 'JavaScript 處理器計算', vendor: 'js', fp16: false }, { backend: 'cpu-js', cpu: hw.cpuModel || null, cores: hw.cores || null, engine_version: o.engineFactory ? 'injected' : 'tiny-1' });\n    },\n    async benchmark(cfg, opts) {\n      const c = Object.assign({}, cfg, { makeBatch: (i) => ({ indices: [i % ((cfg && cfg.nSamples) || DEFAULTS.nSamples)] }) });\n      return BC.stepBenchmark(b, c, Object.assign({}, opts, { isReference: !(opts && opts.reference) && !(opts && opts.fp16), tokensPerStep: (cfg && cfg.seqLen) || DEFAULTS.seqLen }));\n    },\n    async init(assetState, cfg) {\n      const st = o.engineFactory ? o.engineFactory(cfg) : createTinyEngine(cfg);\n      if (assetState && assetState.ckpt) { if (o.engineFactory) await st.load(assetState); else tinyLoad(st, assetState); }\n      return st;\n    },\n    async step(h, batch) { if (h.disposed) throw new Error('handle 已釋放'); return o.engineFactory ? h.step(batch) : tinyStep(h, batch); },\n    async evalLoss(h, batch) { if (o.engineFactory) return h.evalLoss(batch); return { loss: lossOver(h, (batch && batch.indices) || h.cfg.evalBatch) }; },\n    async saveCheckpoint(h) { return o.engineFactory ? h.save() : tinySave(h, o.produced); },\n    async loadCheckpoint(h, cp) { if (o.engineFactory) return h.load(cp); tinyLoad(h, cp); },\n    async dispose(h) { h.disposed = true; if (o.engineFactory && h.dispose) await h.dispose(); },\n    peakMemBytes() { return process.memoryUsage ? process.memoryUsage().rss : 0; },\n  };\n  return b;\n}\n\nmodule.exports = { createCpuJsBackend, createTinyEngine, tinyStep, tinySave, tinyLoad, lossOver, DEFAULTS, compatOf };\n","backend_cpu_py.js":"'use strict';\n// cpu-py 後端：桌面版以 Python 子行程呼叫 lora-train/train_lora.py（train.py 的 sft 階段呼叫的同一支訓練腳本；\n// train.py 本身是七階段管線、沒有步數／檢查點控制，所以 Studio 直接呼叫 train_lora.py）。\n// 純核心、依賴注入：偵測 Python、啟動子行程、檔案系統、時鐘都由呼叫端給，測試時全用假的。子行程一律 windowsHide:true。\nconst B = require('./backend_core.js');\nconst BC = require('./bench_core.js');\nconst C = require('./checkpoint_core.js');\nconst SC = require('./studio_config_core.js');\n\n// 預設的 Python 探測（桌面版真的用；測試不用）：不丟例外，回 { found, path, version, packages }\nfunction defaultDetect(spawnSync) {\n  return function detect() {\n    const code = \"import sys,json\\nr={'version':sys.version.split()[0],'packages':{}}\\nfor m in ('torch','transformers','peft'):\\n    try:\\n        mod=__import__(m); r['packages'][m]=getattr(mod,'__version__','?')\\n    except Exception:\\n        r['packages'][m]=None\\nprint(json.dumps(r))\";\n    for (const cmd of ['python', 'python3', 'py']) {\n      try {\n        const r = spawnSync(cmd, ['-I', '-c', code], { encoding: 'utf8', windowsHide: true, timeout: 20000 });\n        if (r && !r.error && r.status === 0) { const j = JSON.parse(String(r.stdout).trim().split('\\n').pop()); return { found: true, path: cmd, version: j.version, packages: j.packages }; }\n      } catch (e) {}\n    }\n    return { found: false };\n  };\n}\n\n// 解析 train_lora.py（HF Trainer）印出的一行：log 字典、評估、tqdm 進度、[done]、[paused]\nfunction parseProgressLine(line) {\n  const s = String(line).trim(); if (!s) return null;\n  let m;\n  if ((m = s.match(/^\\{.*\\}$/))) {\n    const o = {}; const re = /'([A-Za-z_]+)':\\s*(-?[0-9.]+(?:e[-+]?[0-9]+)?|nan|inf)/gi; let k;\n    while ((k = re.exec(s))) o[k[1]] = /nan|inf/i.test(k[2]) ? NaN : parseFloat(k[2]);\n    if (o.eval_loss !== undefined) return { type: 'eval', evalLoss: o.eval_loss, epoch: o.epoch };\n    if (o.loss !== undefined || o.train_loss !== undefined) return { type: 'log', loss: o.loss !== undefined ? o.loss : o.train_loss, gradNorm: o.grad_norm, lr: o.learning_rate, epoch: o.epoch };\n    return null;\n  }\n  if ((m = s.match(/(\\d+)\\/(\\d+)\\s*\\[[^\\]]*?(?:,\\s*([\\d.]+)(s\\/it|it\\/s))?\\]/))) return { type: 'progress', step: +m[1], total: +m[2], secPerIt: m[3] ? (m[4] === 'it/s' ? 1 / parseFloat(m[3]) : parseFloat(m[3])) : null };\n  if ((m = s.match(/^\\[paused\\]\\s*step=(\\d+)/))) return { type: 'paused', step: +m[1] };\n  if ((m = s.match(/^\\[done\\]\\s*adapter saved to\\s*(.+)$/))) return { type: 'done', dir: m[1] };\n  if (/^(Traceback|[A-Za-z]*Error:|torch\\.cuda|RuntimeError)/.test(s)) return { type: 'error', text: s };\n  return null;\n}\n\n// ---- safetensors（JS 可讀，用來把 HF 檢查點的 LoRA 權重轉成規範化 float32）----\nfunction f16(h) { const s = (h & 0x8000) >> 15, e = (h & 0x7c00) >> 10, f = h & 0x03ff; if (e === 0) return (s ? -1 : 1) * Math.pow(2, -14) * (f / 1024); if (e === 31) return f ? NaN : (s ? -Infinity : Infinity); return (s ? -1 : 1) * Math.pow(2, e - 15) * (1 + f / 1024); }\nfunction readSafetensors(buf) {\n  const hl = Number(buf.readBigUInt64LE(0)), head = JSON.parse(buf.subarray(8, 8 + hl).toString('utf8')), base = 8 + hl, out = [];\n  Object.keys(head).forEach((name) => {\n    if (name === '__metadata__') return; const t = head[name], [a, b] = t.data_offsets, n = t.shape.reduce((x, y) => x * y, 1), d = new Float32Array(n);\n    for (let i = 0; i < n; i++) {\n      if (t.dtype === 'F32') d[i] = buf.readFloatLE(base + a + i * 4);\n      else if (t.dtype === 'F16') d[i] = f16(buf.readUInt16LE(base + a + i * 2));\n      else if (t.dtype === 'BF16') { const x = Buffer.alloc(4); x.writeUInt16LE(buf.readUInt16LE(base + a + i * 2), 2); d[i] = x.readFloatLE(0); }\n      else throw new Error('不支援的 safetensors dtype ' + t.dtype);\n    }\n    out.push({ name, shape: t.shape, data: d, srcDtype: t.dtype });\n  });\n  return out;\n}\nfunction loraTensors(list) {   // 依名稱分成 A／B，名稱保留層名（規範化檔內依名稱排序）\n  const A = [], Bt = []; list.forEach((t) => { if (/lora_A/.test(t.name)) A.push(t); else if (/lora_B/.test(t.name)) Bt.push(t); });\n  return { 'lora_A.f32': A, 'lora_B.f32': Bt };\n}\n\nconst NO_STEP = 'cpu-py 是整段訓練的子行程，不支援逐步呼叫；請用 startRun（暫停＝寫檢查點後結束子行程，續訓＝--resume_from_checkpoint）';\n\n// o: { detect, spawn, killTree, fs(existsSync/readdirSync/writeFileSync/readFileSync/unlinkSync/mkdirSync), path, loraDir, now, sleep, hw:{cpuModel,cores} }\nfunction createCpuPyBackend(o) {\n  const P = o.path || require('path'), now = o.now || (() => Date.now()), sleep = o.sleep || ((ms) => new Promise((r) => setTimeout(r, ms)));\n  const script = () => P.join(o.loraDir, 'train_lora.py');\n  const b = {\n    id: 'cpu-py', capabilities: { perStep: false, run: true, fp16: false },\n    async probe() {\n      let d; try { d = await o.detect(); } catch (e) { d = { found: false, error: String(e && e.message || e) }; }\n      const hw = o.hw || {};\n      const fp = { backend: 'cpu-py', cpu: hw.cpuModel || null, cores: hw.cores || null, python_version: d.version || null, torch_version: d.packages && d.packages.torch || null, engine_version: 'train_lora.py' };\n      const dev = { name: hw.cpuModel || 'CPU', vendor: 'cpu', fp16: false };\n      if (!d || !d.found) return B.probeResult(false, '找不到 Python（請安裝 Python 3.10 以上並裝 lora-train/requirements.txt，或改匯出訓練包到別台訓練）', dev, fp);\n      const missing = ['torch', 'transformers', 'peft'].filter((k) => !(d.packages && d.packages[k]));\n      if (missing.length) return B.probeResult(false, '已找到 Python ' + d.version + '，但缺少套件：' + missing.join('、') + '（見 lora-train/requirements.txt）', dev, fp);\n      if (!o.fs.existsSync(script())) return B.probeResult(false, '找不到訓練腳本 ' + script(), dev, fp);\n      return B.probeResult(true, '', dev, fp);\n    },\n    buildArgs(cfg) {\n      const a = [script(), '--model_name_or_path', cfg.base || 'Qwen/Qwen3-0.6B', '--train_file', cfg.trainFile, '--output_dir', cfg.outputDir];\n      const add = (k, v) => { if (v !== undefined && v !== null && v !== '') a.push(k, String(v)); };\n      add('--num_train_epochs', cfg.epochs); add('--learning_rate', cfg.lr); add('--lora_r', cfg.rank); add('--lora_alpha', cfg.alpha);\n      add('--per_device_train_batch_size', cfg.batch); add('--gradient_accumulation_steps', cfg.accum); add('--max_steps', cfg.maxSteps);\n      add('--save_steps', cfg.saveSteps); add('--logging_steps', cfg.loggingSteps === undefined ? 1 : cfg.loggingSteps); add('--seed', cfg.seed); add('--max_seq_len', cfg.seqLen);\n      add('--val_fraction', cfg.valFraction); add('--stop_file', cfg.stopFile); add('--resume_from_checkpoint', cfg.resumeFrom);\n      return a;\n    },\n    // 電腦要保持可用：留一個核心、不彈視窗\n    // 核心數：cfg.threads（明確指定）＞ Studio 設定（o.config，見 studio_config_core.js）＞ 預設 N−1\n    buildEnv(cfg) { const cores = (o.hw && o.hw.cores) || 2; return { LORA_THREADS: String(cfg.threads || SC.resolveThreads(o.config, cores, cfg.purpose)), PYTHONUNBUFFERED: '1' }; },\n    latestCheckpoint(dir) {\n      if (!o.fs.existsSync(dir)) return null; let best = null;\n      o.fs.readdirSync(dir).forEach((n) => { const m = /^checkpoint-(\\d+)$/.exec(n); if (m && (!best || +m[1] > best.step)) best = { step: +m[1], dir: P.join(dir, n) }; });\n      return best;\n    },\n    // 啟動一次訓練（或續訓）。回傳 run：{ pause(), stop(), done:Promise, events }\n    async startRun(cfg, hooks) {\n      hooks = hooks || {}; const stopFile = cfg.stopFile || P.join(cfg.outputDir, 'PAUSE');\n      try { if (o.fs.existsSync(stopFile)) o.fs.unlinkSync(stopFile); } catch (e) {}\n      const c = Object.assign({}, cfg, { stopFile });\n      const py = (await o.detect()).path || 'python';\n      const child = o.spawn(py, b.buildArgs(c), { cwd: o.loraDir, env: Object.assign({}, o.env || {}, b.buildEnv(c)), windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'] });\n      const run = { child, state: 'running', lastStep: 0, lastLoss: null, errors: [], events: 0, startedAt: now(), exitCode: null, pausedAtStep: null };\n      let buf = ''; const feed = (chunk) => { buf += String(chunk).replace(/\\r/g, '\\n'); const parts = buf.split('\\n'); buf = parts.pop(); parts.forEach((l) => { const e = parseProgressLine(l); if (!e) return; run.events++; e.t = now(); if (e.type === 'progress') run.lastStep = e.step; if (e.type === 'log') { run.lastLoss = e.loss; } if (e.type === 'paused') run.pausedAtStep = e.step; if (e.type === 'error') run.errors.push(e.text); if (hooks.onEvent) hooks.onEvent(e); }); };\n      child.stdout && child.stdout.on('data', feed); child.stderr && child.stderr.on('data', feed);\n      run.done = new Promise((res) => { child.on('exit', (code, sig) => { if (buf) feed('\\n'); run.exitCode = code; run.state = run.state === 'pausing' ? 'paused' : run.state === 'stopping' ? 'stopped' : (code === 0 ? 'finished' : 'failed'); res({ state: run.state, exitCode: code, signal: sig, errors: run.errors }); }); child.on('error', (e) => { run.errors.push(String(e && e.message || e)); run.state = 'failed'; re